// Fast surface lobes for skin/wax, thin leaves and polygonal hair; no diffusion-profile or strand simulation.
export const advancedShadingGLSL=`
vec3 hbScatterDiffuse(float nl,vec3 view,vec3 light,vec3 tint,float skin,float foliage,float thickness){float wrap=max(0.0,(nl+.5)/1.5),back=pow(max(0.0,dot(-light,view)),4.0)*exp(-max(0.0,thickness));return tint*(skin*(wrap+back)+foliage*max(0.0,-nl))*.318309886;}
vec3 hbHairSpecular(vec3 normal,vec3 view,vec3 light,vec3 tangent,vec3 tint,float rough,float shift){vec3 h=view+light;h*=inversesqrt(max(dot(h,h),.000001));if(dot(tangent,tangent)<.000001)tangent=cross(normal,abs(normal.z)<.9?vec3(0,0,1):vec3(0,1,0));vec3 t1=tangent+normal*shift,t2=tangent-normal*(shift+.3);t1*=inversesqrt(max(dot(t1,t1),.000001));t2*=inversesqrt(max(dot(t2,t2),.000001));float exponent=clamp(2.0/max(rough*rough,.001)-2.0,1.0,2048.0),a=sqrt(max(0.0,1.0-pow(dot(t1,h),2.0))),b=sqrt(max(0.0,1.0-pow(dot(t2,h),2.0))),direction=max(0.0,dot(normal,light))+.25*max(0.0,-dot(normal,light));return (vec3(.04)*pow(a,exponent)+tint*.12*pow(b,exponent*.5))*(exponent+2.0)*.159154943*direction;}
vec2 hbEyeUV(vec2 uv,vec3 view,float depth,float iris){return uv-view.xy/max(abs(view.z),.1)*max(depth,0.0)*clamp(iris,0.0,1.0);}
`;
export function advancedDirectChunk(chunk){return chunk.replace('vec3 diffuseColor;','vec3 diffuseColor;\nvec3 hbScatterTint,hbHairTangent;vec4 hbScatter;float hbHairShift;').replace('reflectedLight.directDiffuse += irradiance * BRDF_Lambert( material.diffuseColor );','reflectedLight.directDiffuse += irradiance * BRDF_Lambert( material.diffuseColor )*(1.0-material.hbScatter.x);\nif(material.hbScatter.x>0.0||material.hbScatter.y>0.0)reflectedLight.directDiffuse+=directLight.color*material.diffuseColor*hbScatterDiffuse(dot(geometryNormal,directLight.direction),geometryViewDir,directLight.direction,material.hbScatterTint,material.hbScatter.x,material.hbScatter.y,material.hbScatter.w);\nif(material.hbScatter.z>0.0)reflectedLight.directSpecular+=directLight.color*hbHairSpecular(geometryNormal,geometryViewDir,directLight.direction,material.hbHairTangent,material.diffuseColor,material.roughness,material.hbHairShift)*material.hbScatter.z;');}
